import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Custom ELU CUDA kernel source
custom_elu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void elu_kernel(const float* __restrict__ in_data,
                           float* __restrict__ out_data,
                           float alpha,
                           const int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in_data[idx];
        out_data[idx] = (val > 0.0f) ? val : alpha * (expf(val) - 1.0f);
    }
}

torch::Tensor elu_forward_cuda(torch::Tensor x, float alpha) {
    auto out = torch::zeros_like(x);
    int size = x.numel();

    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    elu_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        alpha,
        size
    );

    return out;
}
"""

# C++ declaration for the above function
custom_elu_cpp_source = """
torch::Tensor elu_forward_cuda(torch::Tensor x, float alpha);
"""

# Build the custom extension
custom_elu = load_inline(
    name="custom_elu",
    cpp_sources=custom_elu_cpp_source,
    cuda_sources=custom_elu_source,
    functions=["elu_forward_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, alpha: float = 1.0):
        super(ModelNew, self).__init__()
        self.alpha = alpha
        self.custom_elu = custom_elu

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.custom_elu.elu_forward_cuda(x, float(self.alpha))
